from __future__ import annotations

import base64
import hashlib
import hmac
import json
import secrets
import sqlite3
import threading
from dataclasses import dataclass
from datetime import datetime, timedelta, timezone
from pathlib import Path
from typing import Any, Mapping, Sequence
from urllib.parse import urlencode

import boto3
from botocore.exceptions import ClientError
from pydantic import BaseModel, ConfigDict, ValidationError, model_validator

from backend.shared.adapters.adapter_contract import (
    EventAdapter,
    EventRecord,
    LogEntry,
    LogSinkAdapter,
    ObjectStorageAdapter,
    QueueAdapter,
    QueueMessage,
    SecretsAdapter,
)

_ALLOWED_PROFILES = ("aws", "onprem")


class RuntimeConfigurationError(ValueError):
    """Raised when runtime profile configuration is missing or invalid."""


class RuntimeConfig(BaseModel):
    model_config = ConfigDict(extra="ignore", frozen=True)

    deployment_profile: str
    aws_region: str | None = None
    aws_endpoint_url: str | None = None
    aws_log_group: str = "kit-log-group"
    aws_log_stream: str = "kit-log-stream"
    aws_event_bus_name: str = "default"
    onprem_root: str | None = None

    @model_validator(mode="after")
    def validate_profile_requirements(self) -> "RuntimeConfig":
        if self.deployment_profile not in _ALLOWED_PROFILES:
            allowed = ", ".join(_ALLOWED_PROFILES)
            raise ValueError(
                f"deployment_profile must be one of [{allowed}] but got {self.deployment_profile!r}"
            )

        if self.deployment_profile == "aws" and not self.aws_region:
            raise ValueError("AWS_REGION is required when DEPLOYMENT_PROFILE=aws")

        if self.deployment_profile == "onprem" and not self.onprem_root:
            raise ValueError("ONPREM_ROOT is required when DEPLOYMENT_PROFILE=onprem")

        return self


@dataclass(frozen=True, slots=True)
class ResolvedRuntimeAdapters:
    profile: str
    object_storage: ObjectStorageAdapter
    queue: QueueAdapter
    events: EventAdapter
    secrets: SecretsAdapter
    logs: LogSinkAdapter


def _utc_now() -> datetime:
    return datetime.now(tz=timezone.utc)


def load_runtime_config(env: Mapping[str, str] | None = None) -> RuntimeConfig:
    source = dict(env or {})
    raw_profile = source.get("DEPLOYMENT_PROFILE")

    if not raw_profile:
        raise RuntimeConfigurationError(
            "DEPLOYMENT_PROFILE must be set to 'aws' or 'onprem' before adapter resolution."
        )

    payload = {
        "deployment_profile": raw_profile,
        "aws_region": source.get("AWS_REGION"),
        "aws_endpoint_url": source.get("AWS_ENDPOINT_URL"),
        "aws_log_group": source.get("AWS_LOG_GROUP", "kit-log-group"),
        "aws_log_stream": source.get("AWS_LOG_STREAM", "kit-log-stream"),
        "aws_event_bus_name": source.get("AWS_EVENT_BUS_NAME", "default"),
        "onprem_root": source.get("ONPREM_ROOT"),
    }

    try:
        config = RuntimeConfig.model_validate(payload)
    except ValidationError as exc:
        errors = "; ".join(_format_validation_error(item) for item in exc.errors())
        raise RuntimeConfigurationError(f"Invalid runtime configuration: {errors}") from exc

    if config.deployment_profile == "onprem":
        try:
            Path(config.onprem_root or "").mkdir(parents=True, exist_ok=True)
        except OSError as exc:
            raise RuntimeConfigurationError(
                f"Invalid runtime configuration: ONPREM_ROOT is not writable: {config.onprem_root!r}"
            ) from exc

    return config


def resolve_runtime_adapters(env: Mapping[str, str] | None = None) -> ResolvedRuntimeAdapters:
    config = load_runtime_config(env)

    if config.deployment_profile == "aws":
        session = boto3.session.Session(region_name=config.aws_region)
        return ResolvedRuntimeAdapters(
            profile="aws",
            object_storage=AwsObjectStorageAdapter(
                _boto3_client(session, "s3", config),
            ),
            queue=AwsQueueAdapter(_boto3_client(session, "sqs", config)),
            events=AwsEventAdapter(
                _boto3_client(session, "events", config),
                event_bus_name=config.aws_event_bus_name,
            ),
            secrets=AwsSecretsAdapter(_boto3_client(session, "secretsmanager", config)),
            logs=AwsLogSinkAdapter(
                _boto3_client(session, "logs", config),
                log_group=config.aws_log_group,
                log_stream=config.aws_log_stream,
            ),
        )

    state = OnPremState(Path(config.onprem_root or ""))
    return ResolvedRuntimeAdapters(
        profile="onprem",
        object_storage=OnPremObjectStorageAdapter(state),
        queue=OnPremQueueAdapter(state),
        events=OnPremEventAdapter(state),
        secrets=OnPremSecretsAdapter(state),
        logs=OnPremLogSinkAdapter(state),
    )


def _format_validation_error(error: Mapping[str, Any]) -> str:
    location = ".".join(str(part) for part in error.get("loc", ()))
    message = str(error.get("msg", "invalid value"))
    return f"{location}: {message}" if location else message


def _boto3_client(session: boto3.session.Session, service_name: str, config: RuntimeConfig) -> Any:
    kwargs: dict[str, Any] = {"region_name": config.aws_region}
    if config.aws_endpoint_url:
        kwargs["endpoint_url"] = config.aws_endpoint_url
    return session.client(service_name, **kwargs)


def _encode_bytes(payload: bytes) -> str:
    return base64.b64encode(payload).decode("ascii")


def _decode_bytes(payload: str) -> bytes:
    return base64.b64decode(payload.encode("ascii"))


class AwsObjectStorageAdapter:
    def __init__(self, client: Any) -> None:
        self._client = client

    def put_object(
        self,
        bucket: str,
        key: str,
        data: bytes,
        *,
        content_type: str | None = None,
    ) -> None:
        params: dict[str, Any] = {"Bucket": bucket, "Key": key, "Body": data}
        if content_type:
            params["ContentType"] = content_type
        self._client.put_object(**params)

    def get_object(self, bucket: str, key: str) -> bytes:
        try:
            response = self._client.get_object(Bucket=bucket, Key=key)
        except ClientError as exc:
            code = exc.response.get("Error", {}).get("Code", "")
            if code in {"NoSuchKey", "404", "NotFound"}:
                raise KeyError(f"Object not found: {bucket}/{key}") from exc
            raise
        return bytes(response["Body"].read())

    def delete_object(self, bucket: str, key: str) -> None:
        self._client.delete_object(Bucket=bucket, Key=key)

    def presign_get(self, bucket: str, key: str, *, expires_in: int = 3600) -> str:
        return str(
            self._client.generate_presigned_url(
                "get_object",
                Params={"Bucket": bucket, "Key": key},
                ExpiresIn=expires_in,
            )
        )


class AwsQueueAdapter:
    def __init__(self, client: Any) -> None:
        self._client = client
        self._queue_urls: dict[str, str] = {}

    def _queue_url(self, queue_name: str) -> str:
        if queue_name not in self._queue_urls:
            response = self._client.get_queue_url(QueueName=queue_name)
            self._queue_urls[queue_name] = str(response["QueueUrl"])
        return self._queue_urls[queue_name]

    def send_message(
        self,
        queue_name: str,
        body: bytes,
        *,
        attributes: Mapping[str, str] | None = None,
    ) -> str:
        message_attributes = {
            name: {"DataType": "String", "StringValue": value}
            for name, value in (attributes or {}).items()
        }
        response = self._client.send_message(
            QueueUrl=self._queue_url(queue_name),
            MessageBody=_encode_bytes(body),
            MessageAttributes=message_attributes,
        )
        return str(response["MessageId"])

    def receive_messages(
        self,
        queue_name: str,
        *,
        max_messages: int = 1,
        visibility_timeout: int = 30,
    ) -> Sequence[QueueMessage]:
        response = self._client.receive_message(
            QueueUrl=self._queue_url(queue_name),
            MaxNumberOfMessages=max_messages,
            VisibilityTimeout=visibility_timeout,
            MessageAttributeNames=["All"],
        )
        messages = response.get("Messages", [])
        return [
            QueueMessage(
                receipt_handle=str(message["ReceiptHandle"]),
                body=_decode_bytes(str(message["Body"])),
                attributes={
                    name: str(spec.get("StringValue", ""))
                    for name, spec in message.get("MessageAttributes", {}).items()
                },
            )
            for message in messages
        ]

    def delete_message(self, queue_name: str, receipt_handle: str) -> None:
        self._client.delete_message(
            QueueUrl=self._queue_url(queue_name),
            ReceiptHandle=receipt_handle,
        )


class AwsEventAdapter:
    def __init__(self, client: Any, *, event_bus_name: str) -> None:
        self._client = client
        self._event_bus_name = event_bus_name

    def publish(self, event: EventRecord) -> str:
        response = self._client.put_events(
            Entries=[
                {
                    "Source": event.metadata.get("source", "backend.runtime"),
                    "DetailType": event.topic,
                    "Detail": json.dumps(event.payload, sort_keys=True),
                    "EventBusName": self._event_bus_name,
                }
            ]
        )
        if int(response.get("FailedEntryCount", 0)) > 0:
            entries = response.get("Entries", [])
            reason = entries[0].get("ErrorMessage", "unknown failure") if entries else "unknown failure"
            raise RuntimeError(f"Failed to publish event: {reason}")
        entry = response.get("Entries", [{}])[0]
        return str(entry.get("EventId", secrets.token_hex(12)))


class AwsSecretsAdapter:
    def __init__(self, client: Any) -> None:
        self._client = client

    def put_secret(self, name: str, value: str) -> None:
        try:
            self._client.create_secret(Name=name, SecretString=value)
        except self._client.exceptions.ResourceExistsException:
            self._client.put_secret_value(SecretId=name, SecretString=value)

    def get_secret(self, name: str) -> str:
        try:
            response = self._client.get_secret_value(SecretId=name)
        except self._client.exceptions.ResourceNotFoundException as exc:
            raise KeyError(f"Secret not found: {name}") from exc
        return str(response["SecretString"])


class AwsLogSinkAdapter:
    def __init__(self, client: Any, *, log_group: str, log_stream: str) -> None:
        self._client = client
        self._log_group = log_group
        self._log_stream = log_stream

    def emit(self, entry: LogEntry) -> str:
        entry_id = entry.entry_id or secrets.token_hex(12)
        payload = {
            "entry_id": entry_id,
            "level": entry.level,
            "message": entry.message,
            "context": entry.context,
            "timestamp": int(entry.timestamp.timestamp() * 1000),
        }
        self._client.put_log_events(
            logGroupName=self._log_group,
            logStreamName=self._log_stream,
            logEvents=[
                {
                    "timestamp": payload["timestamp"],
                    "message": json.dumps(payload, sort_keys=True),
                }
            ],
        )
        return entry_id

    def tail(self, *, limit: int = 100) -> Sequence[LogEntry]:
        response = self._client.get_log_events(
            logGroupName=self._log_group,
            logStreamName=self._log_stream,
            startFromHead=True,
        )
        events = response.get("events", [])
        parsed: list[LogEntry] = []
        for event in events[-limit:]:
            raw_message = json.loads(str(event["message"]))
            parsed.append(
                LogEntry(
                    level=str(raw_message["level"]),
                    message=str(raw_message["message"]),
                    context=dict(raw_message.get("context", {})),
                    entry_id=str(raw_message.get("entry_id")),
                    timestamp=datetime.fromtimestamp(
                        int(raw_message["timestamp"]) / 1000,
                        tz=timezone.utc,
                    ),
                )
            )
        return parsed


class OnPremState:
    def __init__(self, root: Path) -> None:
        self.root = root
        self.storage_root = root / "object-storage"
        self.database_path = root / "adapters.sqlite3"
        self._lock = threading.Lock()

        self.root.mkdir(parents=True, exist_ok=True)
        self.storage_root.mkdir(parents=True, exist_ok=True)
        self._initialize()

    def _connect(self) -> sqlite3.Connection:
        connection = sqlite3.connect(self.database_path)
        connection.row_factory = sqlite3.Row
        return connection

    def _initialize(self) -> None:
        with self._connect() as connection:
            connection.executescript(
                """
                CREATE TABLE IF NOT EXISTS queue_messages (
                    id TEXT PRIMARY KEY,
                    queue_name TEXT NOT NULL,
                    body BLOB NOT NULL,
                    attributes_json TEXT NOT NULL,
                    visible_at REAL NOT NULL,
                    receipt_handle TEXT
                );

                CREATE TABLE IF NOT EXISTS events (
                    id TEXT PRIMARY KEY,
                    topic TEXT NOT NULL,
                    payload_json TEXT NOT NULL,
                    metadata_json TEXT NOT NULL,
                    created_at TEXT NOT NULL
                );

                CREATE TABLE IF NOT EXISTS secrets (
                    name TEXT PRIMARY KEY,
                    value TEXT NOT NULL
                );

                CREATE TABLE IF NOT EXISTS logs (
                    id TEXT PRIMARY KEY,
                    level TEXT NOT NULL,
                    message TEXT NOT NULL,
                    context_json TEXT NOT NULL,
                    created_at TEXT NOT NULL
                );
                """
            )

    def signed_local_url(self, bucket: str, key: str, *, expires_in: int) -> str:
        expires_at = int((_utc_now() + timedelta(seconds=expires_in)).timestamp())
        token_source = f"{bucket}:{key}:{expires_at}".encode("utf-8")
        token = hmac.new(
            key=self.root.as_posix().encode("utf-8"),
            msg=token_source,
            digestmod=hashlib.sha256,
        ).hexdigest()
        return "file://" + str((self.storage_root / bucket / key).resolve()) + "?" + urlencode(
            {"expires_at": expires_at, "signature": token}
        )


class OnPremObjectStorageAdapter:
    def __init__(self, state: OnPremState) -> None:
        self._state = state

    def _path(self, bucket: str, key: str) -> Path:
        return self._state.storage_root / bucket / key

    def put_object(
        self,
        bucket: str,
        key: str,
        data: bytes,
        *,
        content_type: str | None = None,
    ) -> None:
        del content_type
        target = self._path(bucket, key)
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(data)

    def get_object(self, bucket: str, key: str) -> bytes:
        target = self._path(bucket, key)
        if not target.exists():
            raise KeyError(f"Object not found: {bucket}/{key}")
        return target.read_bytes()

    def delete_object(self, bucket: str, key: str) -> None:
        target = self._path(bucket, key)
        if target.exists():
            target.unlink()

    def presign_get(self, bucket: str, key: str, *, expires_in: int = 3600) -> str:
        return self._state.signed_local_url(bucket, key, expires_in=expires_in)


class OnPremQueueAdapter:
    def __init__(self, state: OnPremState) -> None:
        self._state = state

    def send_message(
        self,
        queue_name: str,
        body: bytes,
        *,
        attributes: Mapping[str, str] | None = None,
    ) -> str:
        message_id = secrets.token_hex(16)
        with self._state._lock:
            with self._state._connect() as connection:
                connection.execute(
                    """
                    INSERT INTO queue_messages (id, queue_name, body, attributes_json, visible_at, receipt_handle)
                    VALUES (?, ?, ?, ?, ?, NULL)
                    """,
                    (
                        message_id,
                        queue_name,
                        body,
                        json.dumps(dict(attributes or {}), sort_keys=True),
                        0.0,
                    ),
                )
        return message_id

    def receive_messages(
        self,
        queue_name: str,
        *,
        max_messages: int = 1,
        visibility_timeout: int = 30,
    ) -> Sequence[QueueMessage]:
        now = _utc_now().timestamp()
        visible_again = now + visibility_timeout
        received: list[QueueMessage] = []

        with self._state._lock:
            with self._state._connect() as connection:
                rows = connection.execute(
                    """
                    SELECT id, body, attributes_json
                    FROM queue_messages
                    WHERE queue_name = ? AND visible_at <= ?
                    ORDER BY rowid ASC
                    LIMIT ?
                    """,
                    (queue_name, now, max_messages),
                ).fetchall()

                for row in rows:
                    receipt_handle = secrets.token_hex(16)
                    connection.execute(
                        """
                        UPDATE queue_messages
                        SET visible_at = ?, receipt_handle = ?
                        WHERE id = ?
                        """,
                        (visible_again, receipt_handle, row["id"]),
                    )
                    received.append(
                        QueueMessage(
                            receipt_handle=receipt_handle,
                            body=bytes(row["body"]),
                            attributes=dict(json.loads(str(row["attributes_json"]))),
                        )
                    )

        return received

    def delete_message(self, queue_name: str, receipt_handle: str) -> None:
        with self._state._lock:
            with self._state._connect() as connection:
                connection.execute(
                    """
                    DELETE FROM queue_messages
                    WHERE queue_name = ? AND receipt_handle = ?
                    """,
                    (queue_name, receipt_handle),
                )


class OnPremEventAdapter:
    def __init__(self, state: OnPremState) -> None:
        self._state = state

    def publish(self, event: EventRecord) -> str:
        event_id = event.event_id or secrets.token_hex(16)
        with self._state._lock:
            with self._state._connect() as connection:
                connection.execute(
                    """
                    INSERT INTO events (id, topic, payload_json, metadata_json, created_at)
                    VALUES (?, ?, ?, ?, ?)
                    """,
                    (
                        event_id,
                        event.topic,
                        json.dumps(event.payload, sort_keys=True),
                        json.dumps(event.metadata, sort_keys=True),
                        event.created_at.isoformat(),
                    ),
                )
        return event_id


class OnPremSecretsAdapter:
    def __init__(self, state: OnPremState) -> None:
        self._state = state

    def put_secret(self, name: str, value: str) -> None:
        with self._state._lock:
            with self._state._connect() as connection:
                connection.execute(
                    """
                    INSERT INTO secrets (name, value)
                    VALUES (?, ?)
                    ON CONFLICT(name) DO UPDATE SET value = excluded.value
                    """,
                    (name, value),
                )

    def get_secret(self, name: str) -> str:
        with self._state._lock:
            with self._state._connect() as connection:
                row = connection.execute(
                    "SELECT value FROM secrets WHERE name = ?",
                    (name,),
                ).fetchone()
        if row is None:
            raise KeyError(f"Secret not found: {name}")
        return str(row["value"])


class OnPremLogSinkAdapter:
    def __init__(self, state: OnPremState) -> None:
        self._state = state

    def emit(self, entry: LogEntry) -> str:
        entry_id = entry.entry_id or secrets.token_hex(16)
        with self._state._lock:
            with self._state._connect() as connection:
                connection.execute(
                    """
                    INSERT INTO logs (id, level, message, context_json, created_at)
                    VALUES (?, ?, ?, ?, ?)
                    """,
                    (
                        entry_id,
                        entry.level,
                        entry.message,
                        json.dumps(entry.context, sort_keys=True),
                        entry.timestamp.isoformat(),
                    ),
                )
        return entry_id

    def tail(self, *, limit: int = 100) -> Sequence[LogEntry]:
        with self._state._lock:
            with self._state._connect() as connection:
                rows = connection.execute(
                    """
                    SELECT id, level, message, context_json, created_at
                    FROM logs
                    ORDER BY created_at DESC
                    LIMIT ?
                    """,
                    (limit,),
                ).fetchall()

        ordered = list(reversed(rows))
        return [
            LogEntry(
                level=str(row["level"]),
                message=str(row["message"]),
                context=dict(json.loads(str(row["context_json"]))),
                entry_id=str(row["id"]),
                timestamp=datetime.fromisoformat(str(row["created_at"])),
            )
            for row in ordered
        ]

