from __future__ import annotations

from collections.abc import Iterator

import boto3
import pytest
from moto import mock_aws

from backend.infra.runtime_profiles import (
    AwsEventAdapter,
    AwsLogSinkAdapter,
    AwsObjectStorageAdapter,
    AwsQueueAdapter,
    AwsSecretsAdapter,
    OnPremEventAdapter,
    OnPremLogSinkAdapter,
    OnPremObjectStorageAdapter,
    OnPremQueueAdapter,
    OnPremSecretsAdapter,
    RuntimeConfigurationError,
    load_runtime_config,
