)
from backend.shared.adapters.adapter_contract import EventRecord, LogEntry


AWS_REGION = "us-east-1"
AWS_BUCKET = "contract-bucket"
AWS_QUEUE = "contract-queue"
AWS_LOG_GROUP = "kit-log-group"
AWS_LOG_STREAM = "kit-log-stream"


@pytest.fixture(params=["aws", "onprem"])
def adapter_bundle(tmp_path: pytest.TempPathFactory, request: pytest.FixtureRequest) -> Iterator[tuple[str, object]]:
    profile = str(request.param)

    if profile == "aws":
        with mock_aws():
            s3 = boto3.client("s3", region_name=AWS_REGION)
            s3.create_bucket(Bucket=AWS_BUCKET)

            sqs = boto3.client("sqs", region_name=AWS_REGION)
            sqs.create_queue(QueueName=AWS_QUEUE)

            logs = boto3.client("logs", region_name=AWS_REGION)
            logs.create_log_group(logGroupName=AWS_LOG_GROUP)
            logs.create_log_stream(logGroupName=AWS_LOG_GROUP, logStreamName=AWS_LOG_STREAM)

            env = {
                "DEPLOYMENT_PROFILE": "aws",
                "AWS_REGION": AWS_REGION,
                "AWS_LOG_GROUP": AWS_LOG_GROUP,
                "AWS_LOG_STREAM": AWS_LOG_STREAM,
            }
            yield profile, resolve_runtime_adapters(env)
        return

    env = {
        "DEPLOYMENT_PROFILE": "onprem",
        "ONPREM_ROOT": str(tmp_path / "onprem-runtime"),
    }
    yield profile, resolve_runtime_adapters(env)


def test_profile_resolver_selects_aws_adapters() -> None:
    with mock_aws():
        boto3.client("s3", region_name=AWS_REGION).create_bucket(Bucket=AWS_BUCKET)
