from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Any, Mapping, Protocol, Sequence, runtime_checkable

DeploymentProfile = str


def utc_now() -> datetime:
    return datetime.now(tz=timezone.utc)


@dataclass(frozen=True, slots=True)
class QueueMessage:
    receipt_handle: str
    body: bytes
    attributes: dict[str, str] = field(default_factory=dict)


@dataclass(frozen=True, slots=True)
class EventRecord:
    topic: str
    payload: dict[str, Any]
    metadata: dict[str, str] = field(default_factory=dict)
    event_id: str | None = None
    created_at: datetime = field(default_factory=utc_now)


@dataclass(frozen=True, slots=True)
class LogEntry:
    level: str
    message: str
    context: dict[str, Any] = field(default_factory=dict)
    entry_id: str | None = None
    timestamp: datetime = field(default_factory=utc_now)


@runtime_checkable
class ObjectStorageAdapter(Protocol):
    def put_object(
        self,
        bucket: str,
        key: str,
        data: bytes,
        *,
        content_type: str | None = None,
    ) -> None: ...

    def get_object(self, bucket: str, key: str) -> bytes: ...

    def delete_object(self, bucket: str, key: str) -> None: ...

    def presign_get(self, bucket: str, key: str, *, expires_in: int = 3600) -> str: ...


@runtime_checkable
class QueueAdapter(Protocol):
    def send_message(
        self,
        queue_name: str,
        body: bytes,
        *,
        attributes: Mapping[str, str] | None = None,
    ) -> str: ...

    def receive_messages(
        self,
        queue_name: str,
        *,
        max_messages: int = 1,
        visibility_timeout: int = 30,
    ) -> Sequence[QueueMessage]: ...

    def delete_message(self, queue_name: str, receipt_handle: str) -> None: ...


@runtime_checkable
class EventAdapter(Protocol):
    def publish(self, event: EventRecord) -> str: ...


@runtime_checkable
class SecretsAdapter(Protocol):
    def put_secret(self, name: str, value: str) -> None: ...

    def get_secret(self, name: str) -> str: ...


@runtime_checkable
class LogSinkAdapter(Protocol):
    def emit(self, entry: LogEntry) -> str: ...

    def tail(self, *, limit: int = 100) -> Sequence[LogEntry]: ...


@runtime_checkable
class RuntimeAdapterBundle(Protocol):
    profile: str
    object_storage: ObjectStorageAdapter
    queue: QueueAdapter
    events: EventAdapter
    secrets: SecretsAdapter
    logs: LogSinkAdapter

