def test_event_adapter_contract(adapter_bundle: tuple[str, object]) -> None:
    _, adapters = adapter_bundle

    event_id = adapters.events.publish(
        EventRecord(
            topic="contract.created",
            payload={"entity_id": "123", "status": "created"},
            metadata={"source": "pytest"},
        )
    )

    assert isinstance(event_id, str)
    assert event_id != ""


@pytest.mark.integration
def test_secrets_adapter_contract(adapter_bundle: tuple[str, object]) -> None:
    _, adapters = adapter_bundle

    adapters.secrets.put_secret("db/password", "initial")
    assert adapters.secrets.get_secret("db/password") == "initial"

    adapters.secrets.put_secret("db/password", "rotated")
    assert adapters.secrets.get_secret("db/password") == "rotated"


@pytest.mark.integration
def test_log_sink_contract(adapter_bundle: tuple[str, object]) -> None:
    _, adapters = adapter_bundle

    entry_id = adapters.logs.emit(
        LogEntry(
            level="INFO",
            message="adapter-contract-log",
            context={"request_id": "req-123"},
        )
    )
    assert entry_id

    entries = adapters.logs.tail(limit=10)
    assert entries
    assert entries[-1].message == "adapter-contract-log"
    assert entries[-1].level == "INFO"
    assert entries[-1].context["request_id"] == "req-123"

